const body = $json.body;
const entry = body.entry?.[0];
const change = entry?.changes?.[0];
const value = change?.value;
const message = value?.messages?.[0];

// Si no hay mensaje de texto (puede ser una actualización de estado u otro evento), paramos aquí.
if (!message || message.type !== 'text') {
  return [];
}

return [{
  json: {
    phone_number_id: value.metadata.phone_number_id,
    from: message.from,
    message_text: message.text.body,
  }
}];

// Historial: Supabase nos lo devuelve del más nuevo al más viejo,
// así que lo invertimos para dárselo a la IA en orden cronológico.
const previos = $input.all()
  .map((i) => i.json)
  .filter((m) => m.role && m.content)
  .reverse()
  .map((m) => ({ role: m.role, content: m.content }));

// Ojo: este nodo recibe varios items (uno por mensaje del historial), así que
// hay que usar .first() y no .item, que aquí no existe.
const cfg = $('Buscar prompt del cliente').first().json;

// La IA no sabe qué día de la semana cae cada fecha, así que se equivocaba al
// resolver "el viernes". Le damos los próximos 7 días ya calculados: exactamente
// 7, para que cada nombre de día aparezca UNA sola vez y no pueda elegir mal.
const proximosDias = [];
for (let i = 0; i < 7; i++) {
  const d = $now.plus({ days: i });
  proximosDias.push(`${d.setLocale('es').toFormat('cccc')} = ${d.toFormat('yyyy-MM-dd')}`);
}

// --- Horario de atencion del negocio (configurado en el panel) ---------------
// Los valores por defecto deben coincidir con HORARIO_POR_DEFECTO del panel.
const cal = $('Buscar módulo calendar').first().json.config || {};
const diasLaborables = (cal.dias_laborables || '1,2,3,4,5')
  .split(',')
  .map((s) => parseInt(s, 10))
  .filter((n) => n >= 1 && n <= 7);
// duracion = lo que ocupa la cita. paso = cada cuanto puede empezar una.
// Son cosas distintas: citas de 60 min con paso de 15 permiten reservar a las 10:15.
const duracion = parseInt(cal.duracion_min || '60', 10);
const paso = parseInt(cal.paso_min || '15', 10);

const tramos = [];
if (cal.manana_inicio && cal.manana_fin) tramos.push([cal.manana_inicio, cal.manana_fin]);
if (cal.tarde_inicio && cal.tarde_fin) tramos.push([cal.tarde_inicio, cal.tarde_fin]);
if (!tramos.length) tramos.push(['09:00', '14:00'], ['16:00', '20:00']);

// --- Franjas ya ocupadas segun Google Calendar -------------------------------
const ocupadas = [];
const freeBusy = $('Cargar ocupación').first().json || {};
for (const c of Object.values(freeBusy.calendars || {})) {
  for (const b of c.busy || []) {
    ocupadas.push([new Date(b.start).getTime(), new Date(b.end).getTime()]);
  }
}
const solapa = (ini, fin) => ocupadas.some(([a, b]) => ini < b && fin > a);

// --- Huecos realmente libres de los proximos 7 dias --------------------------
const ahora = $now.toMillis();
const libres = [];
for (let i = 0; i < 7; i++) {
  const dia = $now.plus({ days: i }).startOf('day');
  if (!diasLaborables.includes(dia.weekday)) continue;

  const horas = [];
  for (const [desde, hasta] of tramos) {
    const [h1, m1] = desde.split(':').map(Number);
    const [h2, m2] = hasta.split(':').map(Number);
    const cierre = dia.set({ hour: h2, minute: m2 });
    let t = dia.set({ hour: h1, minute: m1 });
    while (t.plus({ minutes: duracion }) <= cierre) {
      const ini = t.toMillis();
      const fin = t.plus({ minutes: duracion }).toMillis();
      if (ini > ahora && !solapa(ini, fin)) horas.push(t.toFormat('HH:mm'));
      t = t.plus({ minutes: paso });
    }
  }
  if (horas.length) {
    libres.push({
      fecha: dia.toFormat('yyyy-MM-dd'),
      dia: dia.setLocale('es').toFormat('cccc'),
      horas,
    });
  }
}

// Con paso de 15 min salen decenas de horas sueltas por dia, asi que las
// agrupamos en rangos para que el prompt no se dispare.
const aMin = (h) => {
  const [a, b] = h.split(':').map(Number);
  return a * 60 + b;
};
const aTexto = (m) =>
  String(Math.floor(m / 60)).padStart(2, '0') + ':' + String(m % 60).padStart(2, '0');

function rangos(horas) {
  const out = [];
  let ini = null;
  let prev = null;
  for (const h of horas) {
    const m = aMin(h);
    if (prev !== null && m === prev + paso) {
      prev = m;
      continue;
    }
    if (ini !== null) out.push(ini === prev ? aTexto(ini) : aTexto(ini) + '-' + aTexto(prev));
    ini = m;
    prev = m;
  }
  if (ini !== null) out.push(ini === prev ? aTexto(ini) : aTexto(ini) + '-' + aTexto(prev));
  return out.join(', ');
}

const calendario = [
  '=== CALENDARIO REAL (esta es la unica fuente valida de fechas) ===',
  `Hoy es ${$now.setLocale('es').toFormat('cccc')} ${$now.toFormat('yyyy-MM-dd')} (Europe/Madrid).`,
  proximosDias.join('\n'),
  'Reglas de fechas:',
  '- Si el usuario nombra un dia de la semana ("el viernes", "este viernes"), usa EXACTAMENTE la fecha de esta lista.',
  '- Si nombra una fecha concreta ("el 31 de julio"), respetala tal cual y NO la corrijas.',
  '- NUNCA digas a que dia de la semana corresponde una fecha si no aparece en esta lista.',
  '- Los mensajes anteriores de la conversacion pueden contener fechas equivocadas: ignoralas y usa solo esta lista.',
  '- Solo si dice "la semana que viene" o "el viernes que viene" suma 7 dias a la fecha de la lista.',
  '',
  `=== HUECOS LIBRES (citas de ${duracion} min, pueden empezar cada ${paso} min) ===`,
  libres.length
    ? libres.map((d) => `${d.dia} ${d.fecha}: ${rangos(d.horas)}`).join('\n')
    : 'No queda ningun hueco libre en los proximos 7 dias.',
  'Reglas de disponibilidad:',
  `- Los rangos son horas de INICIO posibles: dentro de "09:00-11:00" vale cualquier hora en saltos de ${paso} minutos (09:00, ${aTexto(9 * 60 + paso)}, ...).`,
  '- Si el usuario PREGUNTA que huecos hay, respondele usando esos rangos, sin inventarte ninguno.',
  '- Si el usuario PIDE una hora concreta, NO juzgues si esta libre: limitate a rellenar date y time. De comprobarlo se encarga el sistema.',
].join('\n');

const instrucciones = [
  'Tu tarea es EXTRAER datos y conversar. La disponibilidad la decide el sistema, nunca tu.',
  '',
  'Responde SIEMPRE en JSON con esta forma exacta:',
  '{"reply": "tu respuesta al usuario", "date": "YYYY-MM-DD" o null, "time": "HH:mm" o null, "email": "el email del usuario" o null}',
  '',
  'Para reservar una cita hacen falta TRES datos: fecha, hora y email de contacto.',
  '- date, time y email son los que el usuario haya dicho en CUALQUIER momento de la conversacion, aunque fuera en un mensaje anterior. Pon null solo si de verdad no lo ha dicho nunca.',
  '- Rellena SIEMPRE date y time si el usuario ha mencionado un dia y una hora, AUNQUE creas que esa hora podria estar ocupada.',
  '- NUNCA digas que una hora no esta disponible, y NUNCA ofrezcas horas alternativas por tu cuenta: de eso se encarga el sistema despues de ti.',
  '- En reply: si falta alguno de los tres datos, pide UNICAMENTE el que falte. Si ya tienes los tres, escribe una confirmacion breve.',
  '- No vuelvas a preguntar un dato que el usuario ya te dio antes.',
].join('\n');

const messages = [{ role: 'system', content: cfg.system_prompt || '' }];

if (cfg.knowledge_base) {
  messages.push({
    role: 'system',
    content: 'Base de conocimiento del negocio:\n' + cfg.knowledge_base,
  });
}

messages.push({ role: 'system', content: instrucciones });
messages.push(...previos);
// El calendario va DESPUES del historial, pegado al mensaje actual. Si queda
// enterrado al principio, el modelo se guia por las fechas (a veces erroneas)
// que el mismo dijo en mensajes anteriores.
messages.push({ role: 'system', content: calendario });
messages.push({ role: 'user', content: $('Extraer mensaje').first().json.message_text });

// "libres" viaja también al nodo Comprobar disponibilidad, para no duplicar
// allí el cálculo de huecos.
return [{ json: { messages, libres, duracion } }];

const ia = $input.first().json;
const ctx = $('Preparar contexto').first().json;
const libres = ctx.libres || [];

const aMin = (h) => { const [a, b] = h.split(':').map(Number); return a * 60 + b; };
const dosCifras = (n) => String(n).padStart(2, '0');

// La hora que el usuario ha escrito en ESTE mensaje manda sobre la que
// extrae la IA: se la ha visto inventarse un 'no disponible' con time=null, y
// tambien coger la primera alternativa de su propia lista (le pides 12:30 y
// reserva 12:15). Lo que el usuario escribe es el dato fiable.
function horaDelTexto(txt) {
  const t = String(txt || '').toLowerCase();
  // Se evita el punto como separador suelto: '4.08' es una fecha, no las 04:08.
  const patrones = [
    /\blas\s+(\d{1,2})(?:\s*[:.,'’h]\s*(\d{2}))?/,
    /\b(\d{1,2})\s*[:'’]\s*(\d{2})\b/,
    /\b(\d{1,2})\s*[.,]\s*(\d{2})\s*h\b/,
    /\b(\d{1,2})\s*h\s*(\d{2})\b/,
    /\b(\d{1,2})\s*h\b/,
  ];
  for (const p of patrones) {
    const m = t.match(p);
    if (!m) continue;
    const h = Number(m[1]);
    const min = m[2] === undefined ? 0 : Number(m[2]);
    if (h < 24 && min < 60) return dosCifras(h) + ':' + dosCifras(min);
  }
  return null;
}

const hora = horaDelTexto($('Extraer mensaje').first().json.message_text) || ia.time;

// 1. Sin fecha y hora todavia no hay nada que comprobar: sirve el reply de la
//    IA, que estara pidiendo lo que falte.
if (!ia.date || !hora) {
  return [{ json: { ...ia, time: hora, disponible: false } }];
}

const dia = libres.find((d) => d.fecha === ia.date);
const libre = Boolean(dia && dia.horas.includes(hora));
ia.time = hora;

// 2. Hueco libre y email ya conocido: confirmamos. El texto lo ponemos
//    nosotros porque la IA a veces niega horas que si estan libres.
if (libre && ia.email) {
  const reply =
    '¡Listo! Tu cita queda confirmada para el ' + dia.dia + ' ' + dia.fecha +
    ' a las ' + ia.time + '. Te envío la confirmación a ' + ia.email + '.';
  return [{ json: { ...ia, disponible: true, reply } }];
}

// 3. Hueco libre pero falta el email: lo pedimos AHORA, ya sabiendo que la
//    cita es viable. Nunca al reves: pedir datos para una hora ocupada.
if (libre) {
  const reply =
    'Perfecto, el ' + dia.dia + ' ' + dia.fecha + ' a las ' + ia.time +
    ' está libre. ¿Me dices tu email para enviarte la confirmación?';
  return [{ json: { ...ia, disponible: false, reply } }];
}

// 4. Ocupado o fuera de horario: lo decimos ya, sin pedir mas datos.
//    Las alternativas son las mas CERCANAS a la hora pedida (antes y despues),
//    no las primeras del dia: si pides las 12:00 no te sirve que te ofrezcan las 9.
//    Damos siempre una opcion ANTES (la ultima que cabe) y varias DESPUES,
//    que es como razona quien pide hora: 'un poco antes o un poco despues'.
const pedido = aMin(hora);
const cercanas = (horas, nDespues) => {
  const antes = horas.filter((h) => aMin(h) < pedido).slice(-1);
  const despues = horas.filter((h) => aMin(h) > pedido).slice(0, nDespues);
  return antes.concat(despues);
};

const alternativas = [];
if (dia && dia.horas.length) {
  alternativas.push(dia.dia + ' ' + dia.fecha + ': ' + cercanas(dia.horas, 4).join(', '));
}
for (const d of libres) {
  if (alternativas.length >= 3) break;
  if (d.fecha === ia.date || !d.horas.length) continue;
  alternativas.push(d.dia + ' ' + d.fecha + ': ' + cercanas(d.horas, 3).join(', '));
}

const reply = alternativas.length
  ? 'Lo siento, las ' + ia.time + ' del ' + ia.date + ' no están disponibles. Tengo libre:\n' +
    alternativas.join('\n') + '\n¿Cuál te viene mejor?'
  : 'Lo siento, ahora mismo no me queda ningún hueco libre en los próximos días.';

return [{ json: { ...ia, disponible: false, reply } }];

